      "title": "The Duke's Return",
      "start_block": "B005",
      "end_block": "B019",
      "hook": "A nobleman screams 'This man is an imposter! Arrest him!' while lunging in rage.",
      "cliffhanger": "The Royal Guard Captain refuses the order and salutes Alexander instead, declaring 'No. He is your Duke.'",
      "why": "Instantly establishes a high-stakes identity conflict where the villain tries to arrest the hero, only for the guards to reveal the hero's true power.",
      "context_gap": "None; the viewer immediately sees who is attacking whom and who holds the authority."
    },
    {
      "title": "Treason Exposed",
      "start_block": "B026",
      "end_block": "B053",
      "hook": "Alexander coldly commands 'Read the first' while holding a sealed War Office dossier stamped Top Secret.",
      "cliffhanger": "The Crown Official reads aloud the names of the traitors: 'Lord Henry Sterling' and 'Rupert Ashburn,' causing Rupert to crumble in terror.",
      "why": "Delivers a massive public revelation where evidence proves the villain sold out the hero's men, shifting all power to the hero.",
      "context_gap": "None; the stakes are clear (treason) and the outcome is immediate (names read)."
    },
    {
      "title": "Escape Blocked",
      "start_block": "B078",
      "end_block": "B087",
      "hook": "Rupert frantically points at Lord Sterling screaming 'Sterling handled the report!' as Sterling tries to flee.",
      "cliffhanger": "Sterling throws open the church door to escape, but a stern Police Constable is standing directly outside blocking his path.",
      "why": "Combines betrayal with a physical trap; the villain thinks he can run, but the law is waiting right at the exit.",
      "context_gap": "None; the action is self-contained and the cliffhanger is visually obvious."
    }
  ],
  "moments": [
