      "description": "The Crown Official reads the damning names 'Lord Henry Sterling' and 'Rupert Ashburn' from the documents."
    },
    {
      "start_block": "B085",
      "end_block": "B087",
      "kind": "cliffhanger",
      "description": "Lord Sterling opens the church door to flee, only to find a police constable blocking his escape."
    }
  ]
